/* ============================================
   DRILL MENU COMPONENT
   A drill-in menu for a phone: one level at a
   time, touch-tall rows on one start line, a
   back row naming where it returns to.
   ============================================ */

@layer rift.tokens, rift.preset, rift.components;

@layer rift.components {

.ds-drill-menu {
  /* How far a row's content sits in from the row's own edge. A host that
     lines the labels up with something above it (a header's brand) hangs
     the menu out by this much, so the fills sit in the gutter and the
     words sit on the line. */
  --ds-drill-menu-inset: var(--padding-300);
  /* Touch-tall rows: a control height and one step, so a thumb lands. */
  --ds-drill-menu-row: calc(var(--control-height-default) + var(--padding-200));
  --ds-drill-menu-row-prominent: calc(var(--control-height-default) + var(--padding-400));
  display: block;
  color: var(--color-text-primary);
}

.ds-drill-menu__level {
  display: flex;
  flex-direction: column;
  gap: var(--gap-500);
  scroll-margin-block-start: var(--gap-1000);
}

/* A step slides the new level in along the reading direction: from the
   end going in, from the start coming back. */
.ds-drill-menu__level--in {
  animation: ds-drill-menu-in var(--motion-duration-base) var(--motion-ease-entrance);
}

.ds-drill-menu__level--out {
  animation: ds-drill-menu-out var(--motion-duration-base) var(--motion-ease-entrance);
}

@keyframes ds-drill-menu-in {
  from {
    opacity: 0;
    transform: translateX(calc(var(--ds-inline-sign, 1) * var(--gap-500)));
  }
}

@keyframes ds-drill-menu-out {
  from {
    opacity: 0;
    transform: translateX(calc(var(--ds-inline-sign, 1) * -1 * var(--gap-500)));
  }
}

/* ============================================
   HEAD — back row and level title
   ============================================ */

.ds-drill-menu__head {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--gap-100);
}

.ds-drill-menu__back {
  display: inline-flex;
  align-items: center;
  gap: var(--gap-050);
  min-height: var(--ds-drill-menu-row);
  /* The chevron's side takes one step less (the icon side of a box). */
  padding-inline: var(--padding-100) var(--ds-drill-menu-inset);
  border: none;
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--color-text-secondary);
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  cursor: pointer;
  transition: background-color var(--motion-duration-fast) var(--motion-ease-standard);
}

@media (hover: hover) {
  .ds-drill-menu:not([data-settling]) .ds-drill-menu__back:hover {
    background-color: var(--color-action-passive-bg-hover);
  }
}

.ds-drill-menu__back:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
}

.ds-drill-menu__back-chevron {
  --icon-size: var(--icon-size-600);
}

.ds-drill-menu__title {
  margin: 0;
  padding-inline: var(--ds-drill-menu-inset);
  font-family: var(--font-heading-2-family);
  font-size: var(--font-heading-2-size);
  font-weight: var(--font-heading-2-weight);
  line-height: var(--font-heading-2-line-height);
  letter-spacing: var(--font-heading-2-letter-spacing);
  color: var(--color-text-heading);
}

.ds-drill-menu__title:focus {
  outline: none;
}

.ds-drill-menu__title:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
  border-radius: var(--radius-100);
}

.ds-drill-menu__header {
  padding-inline: var(--ds-drill-menu-inset);
}

/* ============================================
   SECTIONS AND ROWS
   ============================================ */

.ds-drill-menu__section {
  display: flex;
  flex-direction: column;
}

.ds-drill-menu__section-label {
  margin: 0;
  padding: 0 var(--ds-drill-menu-inset) var(--gap-100);
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  color: var(--color-text-tertiary);
}

/* A section's own content after its rows (`content`), held to the menu's
   inset so it lines up with the rows above it. */
.ds-drill-menu__section-content {
  min-width: 0;
  padding-inline: var(--ds-drill-menu-inset);
}

.ds-drill-menu__list {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
}

.ds-drill-menu__item {
  display: flex;
}

/* One shape per row: the fill spans the row, the chevron sits inside it.
   Hover applies only where the device hovers, so a tap leaves none
   behind, and not while the menu settles after a step (`data-settling`,
   until the pointer next moves), so the control that lands under a still
   pointer does not light up. */
.ds-drill-menu__row {
  display: flex;
  align-items: center;
  gap: var(--gap-300);
  width: 100%;
  min-height: var(--ds-drill-menu-row);
  padding: var(--padding-100) var(--ds-drill-menu-inset);
  border: none;
  border-radius: var(--radius-300);
  background: transparent;
  color: var(--color-text-primary);
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  text-align: start;
  text-decoration: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background-color var(--motion-duration-fast) var(--motion-ease-standard);
}

@media (hover: hover) {
  .ds-drill-menu:not([data-settling]) .ds-drill-menu__row:hover {
    background-color: var(--color-action-passive-bg-hover);
  }
}

.ds-drill-menu__row:active {
  background-color: var(--color-action-passive-bg-active);
}

.ds-drill-menu__row:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
}

/* Where the reader is: a quiet fill, never the action colour. */
.ds-drill-menu__row--current {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-drill-menu__row--prominent {
  min-height: var(--ds-drill-menu-row-prominent);
  font-family: var(--font-heading-3-family);
  font-size: var(--font-heading-3-size);
  font-weight: var(--font-heading-3-weight);
  line-height: var(--font-heading-3-line-height);
  letter-spacing: var(--font-heading-3-letter-spacing);
}

/* A two-line row takes the taller row. */
.ds-drill-menu__row:has(.ds-drill-menu__description) {
  min-height: var(--ds-drill-menu-row-prominent);
}

.ds-drill-menu__icon {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: var(--icon-size-600);
  height: var(--icon-size-600);
  color: var(--color-icon-primary);
  --icon-size: var(--icon-size-600);
}

.ds-drill-menu__text {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
}

.ds-drill-menu__label,
.ds-drill-menu__description {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ds-drill-menu__description {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-tertiary);
}

.ds-drill-menu__value {
  flex-shrink: 1;
  min-width: 0;
  max-width: 50%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-tertiary);
}

/* A count on the count badge pair, the "how many" mark AppSidebar,
   BottomNav and TableToolbar share; a word on a quiet pill. */
.ds-drill-menu__badge {
  flex-shrink: 0;
  padding: var(--padding-050) var(--padding-200);
  border-radius: var(--radius-pill);
  background-color: var(--color-bg-container-tertiary);
  color: var(--color-text-secondary);
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-caption-line-height);
}

.ds-drill-menu__badge--count {
  background-color: var(--color-count-badge-bg);
  color: var(--color-count-badge-text);
}

/* On a filled row the quiet pill steps back to the page ground. */
.ds-drill-menu:not([data-settling]) .ds-drill-menu__row:hover .ds-drill-menu__badge:not(.ds-drill-menu__badge--count),
.ds-drill-menu__row--current .ds-drill-menu__badge:not(.ds-drill-menu__badge--count) {
  background-color: var(--color-bg-page-primary);
}

.ds-drill-menu__trail {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  min-width: var(--icon-size-600);
  color: var(--color-icon-primary);
}

.ds-drill-menu__chevron,
.ds-drill-menu__external {
  --icon-size: var(--icon-size-600);
}

} /* @layer rift.components */

'use client';

import React, { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { useLinkComponent, type LinkComponent } from '../../behaviors/LinkProvider';
import { mirrorClass } from '../../behaviors/direction';
import { ChosenMark } from '../Dropdown/Dropdown';
import '../../behaviors/direction.css';
import { holdsCurrent, idOf, isSection, drillMenuPathTo, rowsOf } from './path';
import './DrillMenu.css';
import '../../fonts/material-symbols.css';

export interface DrillMenuItem {
  /** Row text. */
  label: string;
  /**
   * Where the row links. On a row with `items` it is the level's landing
   * page instead: the level opens with an overview row linking to it.
   */
  href?: string;
  /** Stable identity, used in `path`. Defaults to `href`, then `label`. */
  id?: string;
  /** A second line under the label, in the secondary text style. */
  description?: string;
  /** Icon before the label: a Material Symbol name (string) or a custom element, such as a swatch or a brand mark. */
  icon?: string | React.ReactNode;
  /** A pill after the label: a count (a number, or digits with an optional `+`) on the count badge pair, a word such as "New" as a quiet pill. */
  badge?: string | number;
  /** The setting's current value at the row's trailing end, such as "Dark", on a row that drills into a list of choices. */
  value?: string;
  /** The heading of the level this row opens, and the name the back rows below it give that level. Defaults to `label`, for a row whose label is a value (a chosen account) rather than the level's name. */
  title?: string;
  /** Rows on the level this row opens. A row with items drills in instead of navigating. */
  items?: DrillMenuEntry[];
  /**
   * Marks the row as the page being viewed, regardless of the exact match
   * against `currentHref`, for a section that stays current on its child
   * routes.
   */
  current?: boolean;
  /** On an `onClick` row in a list of choices, whether it is the chosen one: true carries the chosen mark, and either value sets `aria-pressed`. */
  selected?: boolean;
  /** The link leaves the site: it opens in a new tab and carries an outward arrow. */
  external?: boolean;
  /**
   * Makes the row an action rather than a link, such as a pick or a copy.
   * The menu stays on its level; a choice list's rows set `selected` too.
   */
  onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
}

/**
 * A group of rows under an optional heading: one level's resources or
 * settings, say, set apart from the rows above it.
 */
export interface DrillMenuSection {
  /** Marks the entry as a section rather than a row. */
  type: 'section';
  /** The heading over the rows. Leave it out for a group set apart by space alone. */
  label?: string;
  /** The section's rows. */
  items: DrillMenuItem[];
  /**
   * `prominent` draws the rows in the heading-3 style on a taller row, for
   * a menu that wants its top level louder. The site header's and the app
   * sidebar's drawers keep the default rows.
   * @default 'default'
   */
  variant?: 'default' | 'prominent';
  /** Stable identity for the React key. Defaults to the label. */
  id?: string;
  /**
   * The section's own content after its rows, for a section that is more
   * than a list of destinations: a chat's history in AppSidebar's drawer,
   * say. It scrolls with the level and leaves with it on a drill.
   */
  content?: React.ReactNode;
}

/** An entry on a level: a row, or a section of rows. */
export type DrillMenuEntry = DrillMenuItem | DrillMenuSection;

const isCount = (badge: string | number) => typeof badge === 'number' || /^\d+\+?$/.test(badge);

/** Props owned by DrillMenu itself — everything else falls through to the `<nav>`. */
type DrillMenuOwnProps = {
  /** The first level's rows and sections. A row with `items` drills into the next level. */
  items: DrillMenuEntry[];
  /** href of the current page: the exactly matching row gets `aria-current="page"` and the current treatment, and every row on the way to it the current treatment. */
  currentHref?: string;
  /** The ids of the rows drilled into, first level first: `[]` is the first level. Pair with `onPathChange`. */
  path?: string[];
  /**
   * The path the menu opens on, when it owns its state. Left out, it opens
   * on the deepest level that holds the current page (`currentHref`, or a
   * row marked `current`), so a reader deep in a section reopens the menu
   * where they are; `[]` opens on the first level always.
   */
  defaultPath?: string[];
  /** Fires with the new path whenever a row drills in or the back row steps out, in both controlled and uncontrolled modes. */
  onPathChange?: (path: string[]) => void;
  /** Fires when a link row is followed, alongside native navigation, such as to close the drawer the menu sits in. */
  onNavigate?: (item: DrillMenuItem, event: React.MouseEvent<HTMLElement>) => void;
  /** Content above the first level's rows, such as a search field. */
  header?: React.ReactNode;
  /** The back row's text on the second level, naming the first. */
  rootLabel?: string;
  /** The back row's accessible name, given the title of the level it returns to. Defaults to "Back to <title>". */
  backLabel?: (title: string) => string;
  /** The overview row's text on a level whose row has an `href`, given that row's label. Defaults to "<label> overview". */
  overviewLabel?: (label: string) => string;
  /** The accessible name of the `<nav>` landmark. */
  navLabel?: string;
  /**
   * The component its links render with, such as Next.js's `Link`, so they
   * navigate through the app's router. Wins over a LinkProvider's; a plain
   * `<a>` when neither is set.
   */
  linkComponent?: LinkComponent;
  /** Additional CSS classes. */
  className?: string;
};

export interface DrillMenuProps
  extends DrillMenuOwnProps,
    Omit<React.ComponentPropsWithRef<'nav'>, keyof DrillMenuOwnProps> {}


/**
 * A drill-in menu for a phone: each level fills the space it is given, a
 * row with children opens the next level in its place, and a back row
 * names the level it returns to. Rows are a touch target tall, with an
 * optional icon, a second line, a current value and a trailing chevron,
 * external arrow or chosen mark, every label on one start line. The level
 * changes with a short slide along the reading direction; focus moves to
 * the new level's title, and back to the row it came from on the way out.
 * The path is uncontrolled by default (`defaultPath`) or controlled with
 * `path` and `onPathChange`.
 */
export function DrillMenu({
  items,
  currentHref,
  path: pathProp,
  defaultPath,
  onPathChange,
  onNavigate,
  header,
  rootLabel = 'Menu',
  backLabel = (title) => `Back to ${title}`,
  overviewLabel = (label) => `${label} overview`,
  navLabel = 'Menu',
  linkComponent,
  className = '',
  ref,
  ...rest
}: DrillMenuProps) {
  const Link = useLinkComponent(linkComponent);
  const [ownPath, setOwnPath] = useState<string[]>(() => defaultPath ?? drillMenuPathTo(items, currentHref));
  const path = pathProp ?? ownPath;
  // Which way the last step went; null until the first step, so the first
  // render neither animates nor moves focus.
  const [direction, setDirection] = useState<'in' | 'out' | null>(null);
  const titleRef = useRef<HTMLHeadingElement>(null);
  const levelRef = useRef<HTMLDivElement>(null);
  // The row to return focus to after stepping out.
  const returnTo = useRef<string | null>(null);

  // Walk the path; a stale id (the items changed under it) stops the walk.
  const trail: DrillMenuItem[] = [];
  let entries = items;
  for (const id of path) {
    const next = rowsOf(entries).find((row) => idOf(row) === id && row.items);
    if (!next) break;
    trail.push(next);
    entries = next.items!;
  }
  const level = trail[trail.length - 1];
  const parent = trail[trail.length - 2];

  const setPath = (next: string[]) => {
    if (pathProp === undefined) setOwnPath(next);
    onPathChange?.(next);
  };
  /* After a step, the new level's control under the pointer (the search
     field where the back row was) would show a hover the reader never
     gave it. The menu marks itself settling until the pointer next
     moves, and hover holds off until then; clicks still land. */
  const settle = (from: HTMLElement) => {
    const nav = from.closest<HTMLElement>('.ds-drill-menu');
    if (!nav) return;
    nav.setAttribute('data-settling', '');
    const done = () => {
      nav.removeAttribute('data-settling');
      nav.removeEventListener('pointermove', done);
    };
    nav.addEventListener('pointermove', done);
  };
  const drillIn = (item: DrillMenuItem) => {
    setDirection('in');
    returnTo.current = null;
    setPath([...trail.map(idOf), idOf(item)]);
  };
  const stepOut = () => {
    setDirection('out');
    returnTo.current = level ? idOf(level) : null;
    setPath(trail.slice(0, -1).map(idOf));
  };

  // Focus follows the step: into the new level's title, or back onto the
  // row the reader came from.
  useLayoutEffect(() => {
    if (direction === null) return;
    const back = returnTo.current;
    const row = back ? levelRef.current?.querySelector<HTMLElement>(`[data-drill-menu-id="${CSS.escape(back)}"]`) : null;
    (row ?? titleRef.current ?? levelRef.current?.querySelector<HTMLElement>('a, button'))?.focus();
    // eslint-disable-next-line react-hooks/exhaustive-deps -- a step, not the direction, moves focus
  }, [trail.length]);

  // A level starts at its top: the scroll area around the menu (a
  // drawer's body) is brought back up to it.
  useEffect(() => {
    if (direction === null) return;
    // Only the vertical scroll moves: scrollIntoView would also slide a
    // scroll area that has any room sideways.
    for (let node = levelRef.current?.parentElement; node; node = node.parentElement) {
      const { overflowY } = getComputedStyle(node);
      if ((overflowY === 'auto' || overflowY === 'scroll') && node.scrollHeight > node.clientHeight) {
        node.scrollTo({ top: 0 });
        break;
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- a step, not the direction, scrolls
  }, [trail.length]);

  const renderRow = (item: DrillMenuItem, variant: 'default' | 'prominent' = 'default') => {
    const id = idOf(item);
    const drills = Boolean(item.items);
    const isCurrent = holdsCurrent(item, currentHref);
    const exact = !drills && (item.current || (currentHref != null && item.href === currentHref));
    const classes = [
      'ds-drill-menu__row',
      variant === 'prominent' && 'ds-drill-menu__row--prominent',
      isCurrent && 'ds-drill-menu__row--current',
    ]
      .filter(Boolean)
      .join(' ');
    const trailing = drills ? (
      <span className="ds-drill-menu__chevron material-symbols-rounded ds-mirror-rtl" aria-hidden="true">
        chevron_right
      </span>
    ) : item.selected ? (
      <ChosenMark className="ds-drill-menu__chosen" />
    ) : item.external ? (
      <span className="ds-drill-menu__external material-symbols-rounded" aria-hidden="true">
        arrow_outward
      </span>
    ) : null;
    const body = (
      <>
        {item.icon != null && (
          <span className="ds-drill-menu__icon" aria-hidden="true">
            {typeof item.icon === 'string' ? <span className={`material-symbols-rounded ${mirrorClass(item.icon)}`}>{item.icon}</span> : item.icon}
          </span>
        )}
        <span className="ds-drill-menu__text">
          <span className="ds-drill-menu__label">{item.label}</span>
          {item.description && <span className="ds-drill-menu__description">{item.description}</span>}
        </span>
        {item.badge !== undefined && (
          <span className={`ds-drill-menu__badge${isCount(item.badge) ? ' ds-drill-menu__badge--count' : ''}`}>{item.badge}</span>
        )}
        {item.value && <span className="ds-drill-menu__value">{item.value}</span>}
        {trailing && <span className="ds-drill-menu__trail">{trailing}</span>}
      </>
    );

    if (drills || item.onClick || !item.href) {
      return (
        <li key={id} className="ds-drill-menu__item">
          <button
            type="button"
            className={classes}
            data-drill-menu-id={id}
            aria-pressed={item.selected !== undefined && !drills ? item.selected : undefined}
            onClick={(event) => {
              if (drills) {
                settle(event.currentTarget);
                drillIn(item);
              }
              else item.onClick?.(event);
            }}
          >
            {body}
          </button>
        </li>
      );
    }
    return (
      <li key={id} className="ds-drill-menu__item">
        <Link
          href={item.href}
          className={classes}
          data-drill-menu-id={id}
          aria-current={exact ? 'page' : undefined}
          {...(item.external ? { target: '_blank', rel: 'noopener noreferrer' } : {})}
          onClick={(event: React.MouseEvent<HTMLElement>) => onNavigate?.(item, event)}
        >
          {body}
        </Link>
      </li>
    );
  };

  // Rows outside any section gather into unnamed groups between sections,
  // so every row sits in a list.
  const groups: { key: string; section?: DrillMenuSection; rows: DrillMenuItem[] }[] = [];
  entries.forEach((entry, index) => {
    if (isSection(entry)) groups.push({ key: entry.id ?? entry.label ?? `section-${index}`, section: entry, rows: entry.items });
    else {
      const last = groups[groups.length - 1];
      if (last && !last.section) last.rows.push(entry);
      else groups.push({ key: `rows-${index}`, rows: [entry] });
    }
  });

  return (
    <nav {...rest} ref={ref} aria-label={navLabel} className={['ds-drill-menu', className].filter(Boolean).join(' ')}>
      <div
        ref={levelRef}
        key={trail.map(idOf).join('/') || 'root'}
        className={['ds-drill-menu__level', direction && `ds-drill-menu__level--${direction}`]
          .filter(Boolean)
          .join(' ')}
      >
        {level ? (
          <div className="ds-drill-menu__head">
            <button type="button" className="ds-drill-menu__back" aria-label={backLabel(parent ? parent.title ?? parent.label : rootLabel)} onClick={(event) => {
                settle(event.currentTarget);
                stepOut();
              }}>
              <span className="ds-drill-menu__back-chevron material-symbols-rounded ds-mirror-rtl" aria-hidden="true">
                chevron_left
              </span>
              <span>{parent ? parent.title ?? parent.label : rootLabel}</span>
            </button>
            <h2 ref={titleRef} tabIndex={-1} className="ds-drill-menu__title">
              {level.title ?? level.label}
            </h2>
          </div>
        ) : (
          header && <div className="ds-drill-menu__header">{header}</div>
        )}

        {level?.href && (
          <ul className="ds-drill-menu__list">
            {renderRow({ label: overviewLabel(level.label), href: level.href, icon: level.icon, id: `${idOf(level)}#overview` })}
          </ul>
        )}

        {groups.map(({ key, section, rows }) => (
          <section key={key} className="ds-drill-menu__section">
            {section?.label && <h3 className="ds-drill-menu__section-label">{section.label}</h3>}
            {rows.length > 0 && (
              <ul className="ds-drill-menu__list">{rows.map((item) => renderRow(item, section?.variant))}</ul>
            )}
            {section?.content && <div className="ds-drill-menu__section-content">{section.content}</div>}
          </section>
        ))}
      </div>
    </nav>
  );
}

/**
 * Where a DrillMenu will open, given its items and the current page: the
 * ids of the rows down to the deepest level that holds it. A host that
 * shows something only on the first level (as SiteHeader's drawer does its
 * footer) reads it to know where the menu opens. It is part of DrillMenu's
 * published API, so the Fast Refresh rule that wants a component module to
 * export only components does not apply to it, as MaskedInput's helpers.
 */
// eslint-disable-next-line react-refresh/only-export-components
export { drillMenuPathTo } from './path';

import type { DrillMenuEntry, DrillMenuItem, DrillMenuSection } from './DrillMenu';

/**
 * The walks DrillMenu takes over its tree, apart from the component so a
 * host can read the same answers: which row is which, which rows hold the
 * current page, and where the menu opens. `drillMenuPathTo` is published
 * from the DrillMenu module; the rest stay internal.
 */

export const isSection = (entry: DrillMenuEntry): entry is DrillMenuSection =>
  (entry as DrillMenuSection).type === 'section';

/** A row's id in a path: its `id`, else its `href`, else its label. */
export const idOf = (item: DrillMenuItem) => item.id ?? item.href ?? item.label;

/** The rows a level lists, sections opened up. */
export const rowsOf = (entries: DrillMenuEntry[]) =>
  entries.flatMap((entry) => (isSection(entry) ? entry.items : [entry]));

/** Whether a row is the current page, or holds it somewhere below. */
export function holdsCurrent(item: DrillMenuItem, currentHref?: string): boolean {
  if (item.current) return true;
  if (currentHref && item.href === currentHref) return true;
  return (item.items ?? []).some((entry) =>
    isSection(entry) ? entry.items.some((child) => holdsCurrent(child, currentHref)) : holdsCurrent(entry, currentHref),
  );
}

/**
 * The path to the deepest level that holds the current page: each row on
 * the way drills in and holds it (it is `current`, its `href` is
 * `currentHref`, or a row below it is). DrillMenu opens there when it is
 * given no `defaultPath`; a host that shows something only on the first
 * level reads the same path to know where the menu will open.
 */
export function drillMenuPathTo(items: DrillMenuEntry[], currentHref?: string): string[] {
  const path: string[] = [];
  let entries = items;
  for (;;) {
    const next = rowsOf(entries).find((row) => row.items?.length && holdsCurrent(row, currentHref));
    if (!next) return path;
    path.push(idOf(next));
    entries = next.items!;
  }
}
